import{_ as s,o as t,c as a,ao as n}from"./chunks/framework.Cg8nWxPv.js";const u=JSON.parse('{"title":"Show a scene in a VSCode tab","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/vscode-tab.md","filePath":"how-to/vscode-tab.md","lastUpdated":null}'),i={name:"how-to/vscode-tab.md"};function o(r,e,h,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="Show-a-scene-in-a-VSCode-tab" tabindex="-1">Show a scene in a VSCode tab <a class="header-anchor" href="#Show-a-scene-in-a-VSCode-tab" aria-label="Permalink to &quot;Show a scene in a VSCode tab {#Show-a-scene-in-a-VSCode-tab}&quot;">​</a></h1><p>The CesiumLink extension runs beside the Julia process and relays every frame to a webview panel, so <strong>a scene on a remote machine needs no forwarded port</strong>. The panel shows the same viewer a browser gets.</p><h2 id="1.-Install-the-extension" tabindex="-1">1. Install the extension <a class="header-anchor" href="#1.-Install-the-extension" aria-label="Permalink to &quot;1. Install the extension {#1.-Install-the-extension}&quot;">​</a></h2><p>Search the Extensions view for <strong>CesiumLink</strong>, or install <a href="https://marketplace.visualstudio.com/items?itemName=disberd.cesiumlink" target="_blank" rel="noreferrer">disberd.cesiumlink</a> from the marketplace page. It needs VSCode 1.102 or later.</p><p>Over Remote-SSH, install it <strong>from the remote window</strong>. VSCode installs the extension on the host that owns the workspace, and only a remote window owns a remote workspace.</p><p><strong>The extension host and the Julia process must share a filesystem.</strong> The extension ships no Cesium: it reads the built viewer tree the server records. A scene on a third machine reports the path it looked for and opens nothing.</p><h3 id="Building-it-from-this-repository-instead" tabindex="-1">Building it from this repository instead <a class="header-anchor" href="#Building-it-from-this-repository-instead" aria-label="Permalink to &quot;Building it from this repository instead {#Building-it-from-this-repository-instead}&quot;">​</a></h3><p>To run a build of your own, package the sources:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extension</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @vscode/vsce</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>Install the <code>.vsix</code> it writes with <strong>Extensions: Install from VSIX…</strong> in the command palette. Over Remote-SSH, run that command in the remote window.</p><p><strong>A rebuilt <code>.vsix</code> whose version did not change installs nothing, and says nothing.</strong> Raise the version in <code>extension/package.json</code>, or install from the command line with <code>--force</code>.</p><h2 id="2.-Open-a-scene" tabindex="-1">2. Open a scene <a class="header-anchor" href="#2.-Open-a-scene" aria-label="Permalink to &quot;2. Open a scene {#2.-Open-a-scene}&quot;">​</a></h2><p>Start a scene as usual. The port does not matter:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">register_module!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(server, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">vendored</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:primitives</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>Run <strong>CesiumLink: Pick a Scene</strong>. Each row is a scene this user serves, and the panel opens on the row you pick. Every row, a lone scene&#39;s included, carries a <strong>Stop this scene</strong> button. The button stops the server it names over the socket, exactly as <code>stop_server</code> does. It is the only action here that reaches into your Julia process.</p><p>The last row, <strong>Enter a host and port</strong>, reaches a scene that writes no discovery file, such as a server you forwarded a port from. The extension still needs a viewer tree. It takes that from the <code>cesiumLink.distDir</code> setting, and asks for a path when the setting is empty. Set <code>distDir</code> once, and manual entry then costs one prompt instead of two.</p><p><a href="/CesiumLink.jl/previews/PR31/reference/server#CesiumLink.start_server"><code>start_server</code></a> names a scene after the directory it started in, so every row reads <code>CesiumLink</code> by default. The port and the start time beside the title tell two scenes apart. Pass <code>title</code> to name a scene yourself:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;coverage, 12 GHz&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The list comes from a file each server writes for itself — see <a href="/CesiumLink.jl/previews/PR31/reference/server#CesiumLink.discovery_dir"><code>discovery_dir</code></a>. The extension skips a scene whose port no longer answers, so a crashed session leaves no row.</p><h2 id="3.-Let-a-scene-open-its-own-tab" tabindex="-1">3. Let a scene open its own tab <a class="header-anchor" href="#3.-Let-a-scene-open-its-own-tab" aria-label="Permalink to &quot;3. Let a scene open its own tab {#3.-Let-a-scene-open-its-own-tab}&quot;">​</a></h2><p>From a terminal <strong>inside VSCode</strong>, a scene opens its own tab and you run no command:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>The <code>open</code> keyword controls this. Under its default, the same script under SSH, in CI or in the test suite opens nothing and prints nothing.</p><table tabindex="0"><thead><tr><th style="text-align:right;"><code>open</code></th><th style="text-align:right;">What happens</th></tr></thead><tbody><tr><td style="text-align:right;"><code>:auto</code></td><td style="text-align:right;">Asks for a tab from a VSCode terminal. Silent everywhere else.</td></tr><tr><td style="text-align:right;"><code>true</code></td><td style="text-align:right;">Asks wherever it runs, and says why it could not.</td></tr><tr><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Never asks.</td></tr></tbody></table><p><strong>Which window the tab opens in.</strong> A terminal of a remote window names the socket that reaches that window, so the tab opens where you started the scene. VSCode publishes such a socket for remote windows alone, so a local terminal sends the request to whichever window is active.</p><p><strong>VSCode asks you for permission before the tab opens, and asks again for every scene</strong> until you tick <em>&quot;do not ask again for this extension&quot;</em> in that dialog. The server does not wait for your answer: the scene serves while the dialog stands. Pass <code>open = false</code> for a scene that must open nothing.</p><p>A failed tab never costs you the scene. A missing extension, a missing <code>code</code> program and a refused request each cost one <code>@debug</code> line.</p><h2 id="What-the-panel-does,-and-does-not,-do" tabindex="-1">What the panel does, and does not, do <a class="header-anchor" href="#What-the-panel-does,-and-does-not,-do" aria-label="Permalink to &quot;What the panel does, and does not, do {#What-the-panel-does,-and-does-not,-do}&quot;">​</a></h2><p><strong>Close the tab and the server keeps serving.</strong> The panel closes the socket and nothing else. The scene belongs to your REPL, and <a href="/CesiumLink.jl/previews/PR31/reference/server#CesiumLink.stop_server"><code>stop_server</code></a> stops it.</p><p><strong>Stop the server and the panel says so.</strong> A red banner appears over the scene, which stays drawn and interactive. Its one action is to pick another scene: a restarted server binds a new port, so the address the panel held is dead.</p><p><strong>The fullscreen button enters Zen Mode.</strong> A webview cannot go fullscreen, so the button asks for the nearest state the editor has: one editor group, no bars, and the window itself full screen. Click it again to leave. Two effects follow:</p><ul><li><p>an editor group beside the panel is maximized away on the way in, and comes back <strong>evenly sized</strong> on the way out. VSCode reports no group widths, so a split you sized by hand cannot be put back;</p></li><li><p><code>zenMode.centerLayout</code> is held off while Zen Mode is on, and your own value is written back when you leave. Leave Zen Mode another way — Escape twice — and it stays off until you press the button again.</p></li></ul><p>Every other item behaves as it does in a browser — see <a href="./furniture">Choose the on-screen furniture</a>.</p><h2 id="When-nothing-appears" tabindex="-1">When nothing appears <a class="header-anchor" href="#When-nothing-appears" aria-label="Permalink to &quot;When nothing appears {#When-nothing-appears}&quot;">​</a></h2><p>A webview that fails shows a black rectangle and no message. Open the <strong>CesiumLink</strong> output channel. It carries the socket lifecycle — dialled, open, closed with a reason — and every error the page reports.</p><p>Two failures look identical from outside, and the channel names both:</p><ul><li><p>The recorded viewer tree holds no <code>vscode.js</code>. Build it with <code>npm run build</code> in <code>lib/</code>.</p></li><li><p>The recorded path does not exist on this machine, which is the third-machine case above.</p></li></ul><h2 id="Next" tabindex="-1">Next <a class="header-anchor" href="#Next" aria-label="Permalink to &quot;Next {#Next}&quot;">​</a></h2><ul><li><p><a href="/CesiumLink.jl/previews/PR31/reference/server#CesiumLink.start_server"><code>start_server</code></a> and <a href="/CesiumLink.jl/previews/PR31/reference/server#CesiumLink.discovery_dir"><code>discovery_dir</code></a> for the whole surface.</p></li><li><p><a href="./record-replay">Record and replay a session</a> to look at a scene with no Julia at all.</p></li></ul>`,39)])])}const k=s(i,[["render",o]]);export{u as __pageData,k as default};
